from pathlib import Path
import re

root = Path('/home/ubuntu/banking-fintech-roadmap')

routers = '''import { z } from "zod";
import { invokeLLM } from "./_core/llm";
import { COOKIE_NAME } from "@shared/const";
import { getSessionCookieOptions } from "./_core/cookies";
import { systemRouter } from "./_core/systemRouter";
import { publicProcedure, router } from "./_core/trpc";

const questionSchema = {
  type: "object",
  properties: {
    questions: {
      type: "array",
      items: {
        type: "object",
        properties: {
          category: { type: "string" },
          question: { type: "string" },
          why: { type: "string" },
          followUp: { type: "string" },
        },
        required: ["category", "question", "why", "followUp"],
        additionalProperties: false,
      },
    },
  },
  required: ["questions"],
  additionalProperties: false,
} as const;

export const appRouter = router({
  system: systemRouter,
  auth: router({
    me: publicProcedure.query(opts => opts.ctx.user),
    logout: publicProcedure.mutation(({ ctx }) => {
      const cookieOptions = getSessionCookieOptions(ctx.req);
      ctx.res.clearCookie(COOKIE_NAME, { ...cookieOptions, maxAge: -1 });
      return { success: true } as const;
    }),
  }),
  interviews: router({
    generateQuestions: publicProcedure
      .input(z.object({
        company: z.string().min(1).max(160),
        role: z.string().min(1).max(120),
        products: z.string().max(800).default(""),
        metrics: z.string().max(800).default(""),
        risks: z.string().max(800).default(""),
        reporting: z.string().max(800).default(""),
        questionType: z.enum(["mixed", "technical", "domain", "behavioral", "case"]),
        count: z.number().int().min(3).max(8).default(5),
      }))
      .mutation(async ({ input }) => {
        const response = await invokeLLM({
          messages: [
            {
              role: "system",
              content: "You are a senior banking and fintech data interview coach. Create practical, role-specific questions for an experienced regulatory reporting and data professional. Avoid generic trivia. Make questions test product-to-data translation, SQL/modeling, risk, controls, stakeholder judgment, and business understanding. Return JSON only.",
            },
            {
              role: "user",
              content: `Generate ${input.count} ${input.questionType} mock interview questions for this company research profile.\nCompany: ${input.company}\nRole: ${input.role}\nProducts and lifecycle: ${input.products || "Not provided"}\nKey metrics: ${input.metrics || "Not provided"}\nMain risks: ${input.risks || "Not provided"}\nReporting obligations: ${input.reporting || "Not provided"}\nFor each question include the category, the exact interviewer question, why it matters, and one probing follow-up.`,
            },
          ],
          response_format: {
            type: "json_schema",
            json_schema: {
              name: "mock_interview_questions",
              strict: true,
              schema: questionSchema,
            },
          },
          reasoning: { effort: "low" },
        });
        const content = response.choices?.[0]?.message?.content;
        if (typeof content !== "string") throw new Error("The interview generator returned no usable content.");
        const parsed = JSON.parse(content) as { questions: Array<{ category: string; question: string; why: string; followUp: string }> };
        return parsed;
      }),
  }),
});

export type AppRouter = typeof appRouter;
'''
(root / 'server/routers.ts').write_text(routers)

home_path = root / 'client/src/pages/Home.tsx'
home = home_path.read_text()
home = home.replace('import { useMemo, useState } from "react";', 'import { useEffect, useMemo, useState } from "react";\nimport { trpc } from "@/lib/trpc";')
home = home.replace('  BarChart3,\n', '  BarChart3,\n  Bot,\n')
home = home.replace('  Menu,\n', '  Menu,\n  Moon,\n  Pause,\n  Play,\n')
home = home.replace('  Settings2,\n', '  Settings2,\n  Sun,\n  TimerReset,\n')

helper = '''\nfunction formatTime(totalSeconds: number) {\n  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, "0");\n  const seconds = (totalSeconds % 60).toString().padStart(2, "0");\n  return `${minutes}:${seconds}`;\n}\n'''
home = home.replace('function EmptyState({ icon: Icon, title, body }: { icon: React.ComponentType<{ size?: number }>; title: string; body: string }) {\n  return <div className="empty-state"><Icon size={22} /><div><strong>{title}</strong><p>{body}</p></div></div>;\n}\n', 'function EmptyState({ icon: Icon, title, body }: { icon: React.ComponentType<{ size?: number }>; title: string; body: string }) {\n  return <div className="empty-state"><Icon size={22} /><div><strong>{title}</strong><p>{body}</p></div></div>;\n}\n' + helper)

state_block = '''  const [toast, setToast] = useState("");\n  const [theme, setTheme] = useState<"light" | "dark">(() => loadState("roadmap-theme", "light"));\n  const [timerMode, setTimerMode] = useState<"focus" | "short">("focus");\n  const [timerRunning, setTimerRunning] = useState(false);\n  const [timerRemaining, setTimerRemaining] = useState(() => loadState("roadmap-timer-remaining", 25 * 60));\n  const [timerSessions, setTimerSessions] = useState(() => loadState("roadmap-timer-sessions", 0));\n\n  useEffect(() => {\n    document.documentElement.classList.toggle("dark-mode", theme === "dark");\n    saveState("roadmap-theme", theme);\n  }, [theme]);\n\n  useEffect(() => {\n    if (!timerRunning) return;\n    const tick = window.setInterval(() => {\n      setTimerRemaining((current) => {\n        if (current <= 1) {\n          setTimerRunning(false);\n          if (timerMode === "focus") {\n            setTimerSessions((count) => { const next = count + 1; saveState("roadmap-timer-sessions", next); return next; });\n          }\n          return timerMode === "focus" ? 25 * 60 : 5 * 60;\n        }\n        return current - 1;\n      });\n    }, 1000);\n    return () => window.clearInterval(tick);\n  }, [timerRunning, timerMode]);\n\n  useEffect(() => { saveState("roadmap-timer-remaining", timerRemaining); }, [timerRemaining]);\n'''
home = home.replace('  const [toast, setToast] = useState("");\n', state_block)
home = home.replace('  const navigate = (key: NavKey) => { setActive(key); setSidebarOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };\n', '''  const navigate = (key: NavKey) => { setActive(key); setSidebarOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };\n  const changeTimerMode = (mode: "focus" | "short") => { setTimerMode(mode); setTimerRunning(false); setTimerRemaining(mode === "focus" ? 25 * 60 : 5 * 60); };\n  const resetTimer = () => { setTimerRunning(false); setTimerRemaining(timerMode === "focus" ? 25 * 60 : 5 * 60); };\n''')

home = home.replace('<button className="icon-button" onClick={() => notify("All changes are saved locally.")}><CircleCheck size={17} /></button><div className="top-avatar">DR</div>', '<button className="icon-button" onClick={() => notify("All changes are saved locally.")}><CircleCheck size={17} /></button><button className="icon-button theme-toggle" aria-label="Toggle dark mode" onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>{theme === "dark" ? <Sun size={17} /> : <Moon size={17} />}</button><div className="top-avatar">DR</div>')
home = home.replace('{active === "overview" && <Overview skills={skills} projects={projects} stats={skillStats} projectAvg={projectAvg} navigate={navigate} />}', '{active === "overview" && <Overview skills={skills} projects={projects} stats={skillStats} projectAvg={projectAvg} navigate={navigate} timer={{ mode: timerMode, remaining: timerRemaining, running: timerRunning, sessions: timerSessions, onModeChange: changeTimerMode, onToggle: () => setTimerRunning((value) => !value), onReset: resetTimer }} />}')

home = home.replace('function Overview({ skills, projects, stats, projectAvg, navigate }: { skills: typeof initialSkills; projects: typeof initialProjects; stats: { avg: number; criticalReady: number; criticalTotal: number; ready: number }; projectAvg: number; navigate: (key: NavKey) => void }) {', 'function Overview({ skills, projects, stats, projectAvg, navigate, timer }: { skills: typeof initialSkills; projects: typeof initialProjects; stats: { avg: number; criticalReady: number; criticalTotal: number; ready: number }; projectAvg: number; navigate: (key: NavKey) => void; timer: { mode: "focus" | "short"; remaining: number; running: boolean; sessions: number; onModeChange: (mode: "focus" | "short") => void; onToggle: () => void; onReset: () => void } }) {')
home = home.replace('<section className="section-block"><SectionHeader eyebrow="PORTFOLIO RADAR"', '<StudyTimer {...timer} /><section className="section-block"><SectionHeader eyebrow="PORTFOLIO RADAR"')

study_timer = '''\nfunction StudyTimer({ mode, remaining, running, sessions, onModeChange, onToggle, onReset }: { mode: "focus" | "short"; remaining: number; running: boolean; sessions: number; onModeChange: (mode: "focus" | "short") => void; onToggle: () => void; onReset: () => void }) {\n  const total = mode === "focus" ? 25 * 60 : 5 * 60;\n  const progress = Math.max(0, Math.min(100, ((total - remaining) / total) * 100));\n  return <section className="timer-panel panel"><div className="timer-copy"><span className="kicker">FOCUS ENGINE</span><h3>Protect the next block.</h3><p>One focused session is enough to move the roadmap forward. Your completed focus blocks stay on this device.</p><div className="timer-modes"><button className={mode === "focus" ? "timer-mode-active" : ""} onClick={() => onModeChange("focus")}>Focus · 25m</button><button className={mode === "short" ? "timer-mode-active" : ""} onClick={() => onModeChange("short")}>Reset · 5m</button></div></div><div className="timer-dial" style={{ background: `conic-gradient(var(--mint) 0 ${progress}%, rgba(255,255,255,.12) ${progress}% 100%)` }}><div className="timer-dial-inner"><span>{mode === "focus" ? "DEEP WORK" : "RESET"}</span><strong>{formatTime(remaining)}</strong><small>{running ? "in session" : "ready when you are"}</small></div></div><div className="timer-actions"><button className="primary-button timer-button" onClick={onToggle}>{running ? <Pause size={15} /> : <Play size={15} />}{running ? "Pause" : "Start"}</button><button className="secondary-button compact" onClick={onReset}><TimerReset size={15} /> Reset</button><div className="session-count"><strong>{sessions}</strong><span>focus blocks<br />completed</span></div></div></section>\n}\n'''
home = home.replace('\nfunction Roadmap() {', study_timer + '\nfunction Roadmap() {')

# Replace the interview component with an AI-aware version.
pattern = r'function Interviews\([\s\S]*?\nfunction CaseCard'
replacement = '''function Interviews({ sql, updateSql, notify }: { sql: typeof initialSql; updateSql: (sql: typeof initialSql) => void; notify: (message: string) => void }) {\n  const [tab, setTab] = useState<"sql" | "cases" | "stories">("sql");\n  const [company, setCompany] = useState("");\n  const [role, setRole] = useState("Data Analyst");\n  const [products, setProducts] = useState("");\n  const [metrics, setMetrics] = useState("");\n  const [risks, setRisks] = useState("");\n  const [reporting, setReporting] = useState("");\n  const [questionType, setQuestionType] = useState<"mixed" | "technical" | "domain" | "behavioral" | "case">("mixed");\n  const [questionCount, setQuestionCount] = useState(5);\n  const [generated, setGenerated] = useState<Array<{ category: string; question: string; why: string; followUp: string }>>([]);\n  const generateQuestions = trpc.interviews.generateQuestions.useMutation();\n  const handleGenerate = () => {\n    if (!company.trim()) { notify("Add a company name first."); return; }\n    generateQuestions.mutate({ company, role, products, metrics, risks, reporting, questionType, count: questionCount }, {\n      onSuccess: (data) => { setGenerated(data.questions); notify(`${data.questions.length} questions generated from your checklist.`); },\n      onError: () => notify("The generator could not complete this run. Try again in a moment."),\n    });\n  };\n  return <><SectionHeader eyebrow="INTERVIEW EXECUTION" title="Interview hub" description="Your production experience is valuable when you narrate the reasoning, not only the result." action={<button className="secondary-button compact" onClick={() => notify("Mock interview checklist copied.")}><ClipboardList size={15} /> Copy checklist</button>} /><div className="interview-banner"><div className="interview-mark"><BriefcaseBusiness size={24} /></div><div><span className="kicker">THE LIVE-CODING VOICE</span><h3>Say the grain before you write the query.</h3><p>“One output row represents a facility-month. I’ll define the eligible population, confirm join cardinality, and validate the result with control totals.”</p></div></div><section className="ai-generator panel"><div className="ai-generator-head"><div className="ai-spark"><Bot size={19} /></div><div><span className="kicker">AI MOCK INTERVIEW GENERATOR</span><h3>Turn company research into questions worth practicing.</h3><p>Use the checklist below. The generator will create role-specific questions grounded in product, metrics, risks, and reporting context.</p></div><span className="ai-badge">BUILT-IN AI</span></div><div className="ai-form-grid"><label>Company<input value={company} onChange={(e) => setCompany(e.target.value)} placeholder="e.g. Tamara, Tabby, a bank…" /></label><label>Target role<select value={role} onChange={(e) => setRole(e.target.value)}><option>Data Analyst</option><option>Fintech Data Analyst</option><option>Regulatory Reporting Analyst</option><option>Risk Analyst</option><option>Analytics Engineer</option><option>Banking Data Consultant</option></select></label><label>Question mix<select value={questionType} onChange={(e) => setQuestionType(e.target.value as typeof questionType)}><option value="mixed">Mixed interview</option><option value="technical">Technical</option><option value="domain">Domain / product</option><option value="case">Case study</option><option value="behavioral">Behavioral</option></select></label><label>Count<select value={questionCount} onChange={(e) => setQuestionCount(Number(e.target.value))}><option value={3}>3 questions</option><option value={5}>5 questions</option><option value={8}>8 questions</option></select></label><label className="ai-wide">Products and lifecycle<textarea value={products} onChange={(e) => setProducts(e.target.value)} placeholder="What do they sell? Who uses it? What entities and events exist?" /></label><label>Key metrics<textarea value={metrics} onChange={(e) => setMetrics(e.target.value)} placeholder="Revenue, GMV, approval, retention…" /></label><label>Main risks<textarea value={risks} onChange={(e) => setRisks(e.target.value)} placeholder="Credit, fraud, operational, data…" /></label><label className="ai-wide">Reporting obligations<textarea value={reporting} onChange={(e) => setReporting(e.target.value)} placeholder="Regulatory, bureau, audit, SLA, local rules…" /></label></div><div className="ai-generator-footer"><span><CircleCheck size={14} /> Keep assumptions explicit; verify local regulation before interviews.</span><button className="primary-button compact" onClick={handleGenerate} disabled={generateQuestions.isPending}><Sparkles size={15} />{generateQuestions.isPending ? "Generating…" : "Generate questions"}</button></div>{generated.length > 0 && <div className="generated-questions"><div className="generated-heading"><span className="kicker">YOUR PRACTICE SET</span><strong>{generated.length} questions · generated from this checklist</strong></div>{generated.map((item, index) => <div className="generated-question" key={`${item.question}-${index}`}><div className="generated-number">0{index + 1}</div><div><span className="question-category">{item.category}</span><h4>{item.question}</h4><p><strong>Why it matters:</strong> {item.why}</p><p><strong>Follow-up:</strong> {item.followUp}</p></div></div>)}</div>}</section><div className="interview-tabs"><button className={tab === "sql" ? "tab-active" : ""} onClick={() => setTab("sql")}><Terminal size={16} /> SQL patterns</button><button className={tab === "cases" ? "tab-active" : ""} onClick={() => setTab("cases")}><Target size={16} /> Case frameworks</button><button className={tab === "stories" ? "tab-active" : ""} onClick={() => setTab("stories")}><Trophy size={16} /> Behavioral stories</button></div>{tab === "sql" && <div className="sql-table panel"><div className="table-head sql-grid"><span>Pattern</span><span>Technique</span><span>Level</span><span>Status</span><span>Learning note</span></div>{sql.map((item) => <div className="table-row sql-grid" key={item.id}><div className="skill-name"><span className="skill-icon"><Terminal size={14} /></span><strong>{item.pattern}</strong></div><span className="muted-cell">{item.technique}</span><span className={`level level-${item.level.toLowerCase().replaceAll(" ", "-")}`}>{item.level}</span><select value={item.status} onChange={(e) => updateSql(sql.map((row) => row.id === item.id ? { ...row, status: e.target.value as Status } : row))}>{statusOptions.map((option) => <option key={option}>{option}</option>)}</select><input className="note-input" value={item.note} onChange={(e) => updateSql(sql.map((row) => row.id === item.id ? { ...row, note: e.target.value } : row))} placeholder="Add a learning note…" /></div>)}</div>}{tab === "cases" && <div className="case-grid"><CaseCard number="01" title="Root-cause analysis" steps="Understand → quantify impact → reproduce → isolate → fix → validate → monitor" prompt="A regulatory submission count is 2.4% below source totals." /><CaseCard number="02" title="Product metric decline" steps="Define metric → inspect funnel → segment → check data quality → test hypotheses" prompt="Approval is up, but first-payment success is down." /><CaseCard number="03" title="Data model design" steps="Business process → grain → keys → history → access pattern → controls" prompt="Model a BNPL order, facility, installment, refund, and payment flow." /></div>}{tab === "stories" && <div className="story-grid"><StoryCard title="Production issue" body="A missing-record, duplicate, or count-mismatch story with impact and the first failing stage." /><StoryCard title="Ambiguous requirement" body="How you clarified business rules and translated them into SQL and validation logic." /><StoryCard title="Stakeholder tension" body="How you balanced reporting deadline, correctness, and a cross-functional disagreement." /><StoryCard title="Control improvement" body="A repeatable check or documentation change that reduced future investigation effort." /><StoryCard title="Learning gap" body="Use the BNPL question: what changed in your preparation and how did you close the gap?" /></div>}</>;\n}\n\nfunction CaseCard'''
home, count = re.subn(pattern, replacement, home)
if count != 1:
    raise SystemExit(f'Interviews replacement count={count}')

home_path.write_text(home)

css = root / 'client/src/index.css'
css_append = '''\n\n/* Focus engine */\n.timer-panel { display: grid; grid-template-columns: 1.2fr 170px 1fr; align-items: center; gap: 25px; margin-top: 22px; padding: 20px 24px; color: #e9f1ef; background: linear-gradient(115deg, #17313d, #1e3e44); border-color: transparent; overflow: hidden; position: relative; }\n.timer-panel:after { content: ''; position: absolute; width: 260px; height: 260px; border: 1px solid rgba(158,231,194,.12); border-radius: 50%; right: 17%; top: -100px; pointer-events: none; }\n.timer-copy, .timer-actions, .timer-dial { position: relative; z-index: 1; }.timer-panel .kicker { color: #9bd2b5; }.timer-panel h3 { color: #e9f1ef; margin-top: 7px; }.timer-panel p { max-width: 430px; margin: 8px 0 15px; color: #abc1bf; font-size: 11px; line-height: 1.5; }.timer-modes { display: flex; gap: 5px; }.timer-modes button { padding: 7px 9px; border: 1px solid rgba(255,255,255,.15); border-radius: 6px; background: rgba(255,255,255,.06); color: #aac0bf; font: 9px 'DM Mono'; }.timer-modes button.timer-mode-active { color: #18313d; border-color: var(--mint); background: var(--mint); }.timer-dial { width: 145px; height: 145px; display: grid; place-items: center; border-radius: 50%; }.timer-dial-inner { width: 111px; height: 111px; display: grid; place-items: center; align-content: center; border-radius: 50%; background: #17313d; border: 1px solid rgba(158,231,194,.28); }.timer-dial-inner span { color: #8dbda9; font: 8px 'DM Mono'; letter-spacing: .1em; }.timer-dial-inner strong { margin: 5px 0 2px; color: white; font: 700 26px 'Space Grotesk'; letter-spacing: -.04em; }.timer-dial-inner small { color: #88a2a1; font-size: 8px; }.timer-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }.timer-button { padding: 9px 13px; }.timer-actions .secondary-button { color: #e9f1ef; border-color: rgba(255,255,255,.16); background: rgba(255,255,255,.06); }.session-count { display: flex; align-items: center; gap: 8px; margin-left: auto; }.session-count strong { color: var(--mint); font: 700 25px 'Space Grotesk'; }.session-count span { color: #9eb5b3; font: 9px 'DM Mono'; line-height: 1.35; }\n\n/* AI interview generator */\n.ai-generator { margin-top: 18px; padding: 24px; background: linear-gradient(135deg, #f4f9f5, #fff); border-color: #cfe4d6; }.ai-generator-head { display: flex; align-items: flex-start; gap: 13px; position: relative; }.ai-spark { width: 38px; height: 38px; display: grid; place-items: center; flex: 0 0 auto; border-radius: 10px; color: #17313d; background: var(--mint); }.ai-generator-head h3 { margin-top: 7px; }.ai-generator-head p { margin: 6px 0 0; color: #718084; font-size: 11px; line-height: 1.5; }.ai-badge { margin-left: auto; padding: 6px 8px; border-radius: 5px; color: #56816c; background: #e1f4e8; font: 9px 'DM Mono'; letter-spacing: .06em; }.ai-form-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 12px; margin-top: 20px; }.ai-form-grid label { display: grid; gap: 6px; color: #819092; font: 9px 'DM Mono'; letter-spacing: .05em; text-transform: uppercase; }.ai-form-grid input, .ai-form-grid select, .ai-form-grid textarea { width: 100%; resize: vertical; padding: 9px 10px; outline: 0; color: #405054; background: white; border: 1px solid #dce7e1; border-radius: 6px; font: 10px 'Manrope'; text-transform: none; letter-spacing: normal; }.ai-form-grid textarea { min-height: 64px; line-height: 1.4; }.ai-form-grid input:focus, .ai-form-grid select:focus, .ai-form-grid textarea:focus { border-color: #7fc7a2; box-shadow: 0 0 0 3px rgba(127,199,162,.12); }.ai-wide { grid-column: span 2; }.ai-generator-footer { display: flex; align-items: center; justify-content: space-between; gap: 15px; margin-top: 17px; padding-top: 15px; border-top: 1px solid #e5eee8; }.ai-generator-footer > span { display: flex; align-items: center; gap: 7px; color: #7e9a8a; font-size: 10px; }.ai-generator-footer svg { color: #58a879; }.ai-generator-footer button:disabled { opacity: .55; cursor: wait; }.generated-questions { margin-top: 22px; padding-top: 19px; border-top: 1px solid #dce9e1; }.generated-heading { display: flex; align-items: center; gap: 12px; }.generated-heading strong { color: #537467; font: 600 11px 'Space Grotesk'; }.generated-question { display: grid; grid-template-columns: 34px 1fr; gap: 12px; padding: 15px 0; border-bottom: 1px solid #e8efeb; }.generated-question:last-child { border-bottom: 0; padding-bottom: 0; }.generated-number { width: 26px; height: 26px; display: grid; place-items: center; border-radius: 7px; color: #4d9770; background: #e1f4e8; font: 10px 'DM Mono'; }.question-category { color: #7da18e; font: 9px 'DM Mono'; letter-spacing: .1em; text-transform: uppercase; }.generated-question h4 { margin: 6px 0 7px; color: #26383c; font: 700 13px/1.35 'Space Grotesk'; }.generated-question p { margin: 3px 0; color: #718084; font-size: 10px; line-height: 1.45; }.generated-question p strong { color: #577065; }\n\n/* Richer card motion */\n.week-card { position: relative; transform: translateZ(0); }.week-card:before { content: ''; position: absolute; inset: 0 auto 0 0; width: 3px; background: var(--mint); opacity: 0; transform: scaleY(.35); transition: opacity .22s var(--ease-out), transform .22s var(--ease-out); transform-origin: center; }.week-card:hover { transform: translateX(5px); box-shadow: 0 15px 34px rgba(25,38,49,.1); }.week-card:hover:before, .week-card.week-expanded:before { opacity: 1; transform: scaleY(1); }.mini-project { transform: translateZ(0); }.mini-project:hover { transform: translateY(-7px) rotate(-.4deg); box-shadow: 0 18px 34px rgba(25,38,49,.12); }.mini-project:active { transform: translateY(-2px) scale(.99); }\n\n/* Dark mode */\n.dark-mode { color-scheme: dark; --ink: #e7eff0; --ink-soft: #a1b1b3; --line: #30444d; --paper: #1b2d37; --mist: #111e28; --shadow: 0 18px 45px rgba(0,0,0,.18); }.dark-mode body, .dark-mode .app-shell { background: var(--mist); color: var(--ink); }.dark-mode .topbar { background: rgba(17,30,40,.88); border-color: var(--line); }.dark-mode .crumb strong, .dark-mode .metric-card strong, .dark-mode .panel h3, .dark-mode .section-header h2, .dark-mode .week-title strong, .dark-mode .mini-project strong, .dark-mode .detail-hero h3, .dark-mode .generated-question h4 { color: var(--ink); }.dark-mode .search-box, .dark-mode .icon-button, .dark-mode .metric-card, .dark-mode .panel, .dark-mode .week-card, .dark-mode .mini-project, .dark-mode .resource-card, .dark-mode .case-card, .dark-mode .story-card, .dark-mode .filter-tabs button, .dark-mode .roadmap-summary span { color: var(--ink); background: #1b2d37; border-color: var(--line); }.dark-mode .search-box input, .dark-mode .note-input, .dark-mode .table-row select, .dark-mode .detail-progress select, .dark-mode .ai-form-grid input, .dark-mode .ai-form-grid select, .dark-mode .ai-form-grid textarea { color: var(--ink); background: #172832; border-color: #3a515a; }.dark-mode .table-head, .dark-mode .project-story, .dark-mode .case-steps { background: #172832; }.dark-mode .table-row, .dark-mode .next-row, .dark-mode .week-detail, .dark-mode .generated-question { border-color: #30444d; }.dark-mode .muted-cell, .dark-mode .evidence-cell, .dark-mode .week-focus, .dark-mode .section-header p, .dark-mode .panel-lede, .dark-mode .detail-hero p, .dark-mode .resource-card p, .dark-mode .case-prompt, .dark-mode .story-card p, .dark-mode .next-row span { color: #a0b1b4; }.dark-mode .donut-hole { background: #1b2d37; }.dark-mode .tracker-note, .dark-mode .resource-note, .dark-mode .schedule-panel { background: #183329; border-color: #2a5a48; }.dark-mode .ai-generator { background: linear-gradient(135deg, #1c352f, #1b2d37); border-color: #35634e; }.dark-mode .ai-generator-head p, .dark-mode .ai-generator-footer > span { color: #a7bdb1; }.dark-mode .ai-generator-footer, .dark-mode .generated-questions { border-color: #35634e; }.dark-mode .generated-question p, .dark-mode .generated-heading strong { color: #a7bdb1; }.dark-mode .generated-question p strong, .dark-mode .generated-question h4 { color: #dcebe4; }.dark-mode .ai-generator .kicker, .dark-mode .detail-label { color: #9bc9b2; }.dark-mode .resource-provider, .dark-mode .resource-link, .dark-mode .story-structure { color: #9db1b1; }.dark-mode .secondary-button { color: var(--ink); background: #1b2d37; border-color: var(--line); }.dark-mode .theme-toggle { color: #f2c87b; }\n\n@media (max-width: 1100px) { .timer-panel { grid-template-columns: 1fr 145px; }.timer-actions { grid-column: 1 / 3; }.ai-form-grid { grid-template-columns: repeat(2, 1fr); } }\n@media (max-width: 560px) { .timer-panel { grid-template-columns: 1fr; gap: 16px; }.timer-dial { margin: 0 auto; }.timer-actions { grid-column: auto; }.session-count { margin-left: auto; }.ai-form-grid { grid-template-columns: 1fr; }.ai-wide { grid-column: auto; }.ai-generator-footer { align-items: flex-start; flex-direction: column; }.ai-badge { display: none; }.generated-heading { align-items: flex-start; flex-direction: column; gap: 5px; } }\n'''
